        addInstrumentationBefore(node);
        return true;
    }

    if (node instanceof VariableDeclaration) {
        parent.addChildBefore(buildInstrumentationStatement(node.getLineno()), node);
        return true;
    }

    // Default case: add instrumentation before the node
    addInstrumentationBefore(node);
    return true;
}

